"""Poll selectors when sandboxed socketpair wakeup writes are unavailable."""
import selectors

_select = selectors.EpollSelector.select


def _poll_select(self, timeout=None):
    return _select(self, 0.01 if timeout is None else min(timeout, 0.01))


selectors.EpollSelector.select = _poll_select
